import * as THREE from 'three';
import * as xb from 'xrblocks';

const COUNTDOWN_IMAGES = [
  'images/start1.webp',
  'images/start2.webp',
  'images/start3.webp',
  'images/startGo.webp',
];

const COMPUTER_IMAGES = {
  rock: 'images/gestureFistLeft.webp',
  scissors: 'images/gestureScissorsLeft.webp',
  paper: 'images/gesturePaperLeft.webp',
};

const PLAYER_IMAGES = {
  rock: 'images/gestureFistRight.webp',
  scissors: 'images/gestureScissorsRight.webp',
  paper: 'images/gesturePaperRight.webp',
};

const RESULT_IMAGES = {
  tie: 'images/resultTie.webp',
  win: 'images/resultWin.webp',
  lose: 'images/resultLose.webp',
};

const CHOICES = ['rock', 'paper', 'scissors'];
const GESTURE_CHOICES = {
  fist: 'rock',
  'open-palm': 'paper',
  spread: 'paper',
  victory: 'scissors',
};
const BEATS = {rock: 'scissors', paper: 'rock', scissors: 'paper'};

const OUTCOME_PHRASES = {
  tie: ['A draw!', "We've matched.", 'Great minds think alike.'],
  win: ['You got me.', 'Nicely done, you win.', 'The victory is yours.'],
  lose: ['Victory is mine!', 'I got you that time.', 'The round goes to me.'],
};

export class GameRps extends xb.Script {
  constructor() {
    super();
    this.state = 'idle';
    this.captureScores = new Map();
    this.timers = new Set();

    this.countdownImage = new xb.UIImage({
      src: 'images/startStart.webp',
      ariaLabel: 'Game countdown',
      style: {width: 180, height: 100, objectFit: 'contain'},
    });
    this.computerImage = this.createPlayImage('Computer gesture');
    this.playerImage = this.createPlayImage('Your gesture');
    this.resultImage = new xb.UIImage({
      src: 'images/gestureEmpty.webp',
      ariaLabel: 'Round result',
      style: {width: 116, height: 76, objectFit: 'contain'},
    });
    this.primaryText = new xb.UIText({
      text: "Let's play Rock Paper Scissors!",
      style: {
        fontSize: 28,
        fontWeight: 'bold',
        textAlign: 'center',
      },
    });
    this.secondaryText = new xb.UIText({
      text: 'Show a thumbs-up gesture to start.',
      style: {fontSize: 20, textAlign: 'center'},
    });

    const playRow = new xb.UIPanel({
      style: {
        width: '100%',
        flexDirection: 'row',
        justifyContent: 'center',
        alignItems: 'center',
        gap: 22,
      },
      children: [
        this.createPlayerPanel('COMPUTER', this.computerImage),
        new xb.UIImage({
          src: 'images/resultVS.webp',
          ariaLabel: 'Versus',
          style: {width: 78, height: 78, objectFit: 'contain'},
        }),
        this.createPlayerPanel('YOU', this.playerImage),
      ],
    });

    this.card = new xb.UICard({
      size: {width: 0.92, height: 'auto'},
      manipulation: true,
      edge: {scale: true},
      style: {
        alignItems: 'center',
      },
      children: [
        new xb.UIExitButton(),
        new xb.UIText({
          text: 'ROCK - PAPER - SCISSORS',
          style: {
            fontSize: 20,
            fontWeight: 'bold',
            textAlign: 'center',
          },
        }),
        this.countdownImage,
        playRow,
        this.resultImage,
        this.primaryText,
        this.secondaryText,
      ],
    });
    this.card.name = 'Rock Paper Scissors card';
    this.add(this.card);
  }

  createPlayImage(ariaLabel) {
    return new xb.UIImage({
      src: 'images/gestureUnknown.webp',
      ariaLabel,
      style: {width: 150, height: 150, objectFit: 'contain'},
    });
  }

  createPlayerPanel(label, image) {
    return new xb.UIPanel({
      style: {
        width: 210,
        padding: 14,
        gap: 8,
        alignItems: 'center',
      },
      children: [
        new xb.UIText({
          text: label,
          style: {fontSize: 17, textAlign: 'center'},
        }),
        image,
      ],
    });
  }

  init() {
    this.add(new THREE.HemisphereLight(0xffffff, 0x64748b, 3));
    this.card.position.set(0, xb.user.height + 0.05, -1.35);

    const gestures = xb.core.gestureRecognition;
    this.onGesture = (event) => this.handleGesture(event.detail);
    gestures.addEventListener('gesturestart', this.onGesture);
    gestures.addEventListener('gestureupdate', this.onGesture);
  }

  handleGesture({name, confidence}) {
    if (name === 'thumbs-up' && this.state === 'idle') {
      this.startRound();
      return;
    }
    const choice = GESTURE_CHOICES[name];
    if (this.state !== 'capture' || !choice) return;
    this.captureScores.set(
      choice,
      Math.max(confidence, this.captureScores.get(choice) ?? 0)
    );
  }

  startRound() {
    this.state = 'countdown';
    this.captureScores.clear();
    this.computerImage.src = 'images/gestureUnknown.webp';
    this.playerImage.src = 'images/gestureUnknown.webp';
    this.resultImage.src = 'images/gestureEmpty.webp';
    this.primaryText.text = 'Ready?';
    this.secondaryText.text = 'Make rock, paper, or scissors after GO.';

    COUNTDOWN_IMAGES.forEach((image, index) => {
      this.schedule(() => {
        this.countdownImage.src = image;
        if (index === COUNTDOWN_IMAGES.length - 1) this.beginCapture();
      }, index * 700);
    });
  }

  beginCapture() {
    this.state = 'capture';
    this.primaryText.text = 'Throw now!';
    this.captureScores.clear();
    this.schedule(() => this.finishRound(), 1100);
  }

  finishRound() {
    const playerChoice = this.bestCapturedChoice();
    if (!playerChoice) {
      this.state = 'result';
      this.primaryText.text = "I didn't catch your gesture.";
      this.secondaryText.text = 'Show thumbs up when you want to retry.';
      this.schedule(() => this.reset(), 1800);
      return;
    }

    const computerChoice = CHOICES[Math.floor(Math.random() * CHOICES.length)];
    const result = this.getOutcome(playerChoice, computerChoice);
    this.state = 'result';
    this.computerImage.src = COMPUTER_IMAGES[computerChoice];
    this.playerImage.src = PLAYER_IMAGES[playerChoice];
    this.resultImage.src = RESULT_IMAGES[result];
    this.primaryText.text = this.randomPhrase(result);
    this.secondaryText.text = `${this.titleCase(playerChoice)} vs ${this.titleCase(computerChoice)}`;
    this.schedule(() => this.reset(), 2600);
  }

  bestCapturedChoice() {
    let bestChoice;
    let bestScore = 0;
    for (const [choice, score] of this.captureScores) {
      if (score > bestScore) {
        bestChoice = choice;
        bestScore = score;
      }
    }
    return bestChoice;
  }

  getOutcome(playerChoice, computerChoice) {
    if (playerChoice === computerChoice) return 'tie';
    return BEATS[playerChoice] === computerChoice ? 'win' : 'lose';
  }

  randomPhrase(result) {
    const phrases = OUTCOME_PHRASES[result];
    return phrases[Math.floor(Math.random() * phrases.length)];
  }

  titleCase(value) {
    return value[0].toUpperCase() + value.slice(1);
  }

  reset() {
    this.state = 'idle';
    this.countdownImage.src = 'images/startStart.webp';
    this.primaryText.text = "Let's play again!";
    this.secondaryText.text = 'Show a thumbs-up gesture to start.';
  }

  schedule(callback, delayMs) {
    const timer = window.setTimeout(() => {
      this.timers.delete(timer);
      callback();
    }, delayMs);
    this.timers.add(timer);
  }

  dispose() {
    const gestures = xb.core.gestureRecognition;
    gestures?.removeEventListener('gesturestart', this.onGesture);
    gestures?.removeEventListener('gestureupdate', this.onGesture);
    for (const timer of this.timers) window.clearTimeout(timer);
    this.timers.clear();
  }
}

import * as xb from 'xrblocks';

import {GameRps} from './GameRps.js';

const options = new xb.Options();
options.enableReticles();
options.enableGestures();
options.simulator.defaultMode = xb.SimulatorMode.POSE;
options.simulator.defaultHand = xb.Handedness.RIGHT;
options.setAppTitle('Rock Paper Scissors');
options.setAppDescription(
  'Show thumbs up to start, then play with a hand gesture.'
);

const gestureRecognizer = new xb.HeuristicGestureRecognizer();
gestureRecognizer.registerGesture('victory', detectVictoryGesture, {
  enabled: true,
});
options.gestures.setGestureRecognizer(gestureRecognizer);

function detectVictoryGesture(context) {
  const indexStraight = xb.getFingerStraightness(context, 'index');
  const middleStraight = xb.getFingerStraightness(context, 'middle');
  const ringCurled = xb.getFingerCurl(context, 'ring');
  const pinkyCurled = xb.getFingerCurl(context, 'pinky');
  const indexMiddleSpread = xb.getFingerSpread(context, 'index', 'middle');

  const otherFingersClosed = xb.average([ringCurled, pinkyCurled]);
  const extendedPair = xb.average([indexStraight, middleStraight]);
  const foldedPair = xb.clamp01((otherFingersClosed - 0.15) / 0.65);
  const separatedPair = xb.clamp01(indexMiddleSpread);
  const middleGate = xb.clamp01((middleStraight - 0.2) / 0.55);
  const confidence = xb.clamp01(
    middleGate * (extendedPair * 0.55 + separatedPair * 0.25 + foldedPair * 0.2)
  );

  return {
    confidence,
    data: {extendedPair, foldedPair, separatedPair},
  };
}

async function start() {
  xb.add(new GameRps());
  await xb.init(options);
}

document.addEventListener('DOMContentLoaded', start);

import type * as MEDIAPIPE from '@mediapipe/tasks-audio';
import {
  DetectorBackendContext,
  BaseDetectorBackend,
  NormalizedAudio,
} from '../SoundDetectorBackend';
import {AudioClassifierResult} from '../DetectedSounds';

let FilesetResolver: typeof MEDIAPIPE.FilesetResolver | undefined;
let AudioClassifier: typeof MEDIAPIPE.AudioClassifier | undefined;

// --- Attempt Dynamic Import ---
async function loadMediaPipeModule() {
  if (FilesetResolver && AudioClassifier) {
    return;
  }
  try {
    const mediapipeModule = await import('@mediapipe/tasks-audio');
    FilesetResolver = mediapipeModule.FilesetResolver;
    AudioClassifier = mediapipeModule.AudioClassifier;
    console.log("'@mediapipe/tasks-audio' module loaded successfully.");
  } catch (error) {
    console.error('Failed to load MediaPipe module:', error);
    throw error;
  }
}

export class MediaPipeDetectorBackend extends BaseDetectorBackend {
  private chunkSamples = 16000;
  private accumulatedAudio: number[] = [];

  private audioClassifier: MEDIAPIPE.AudioClassifier | null = null;

  constructor(context: DetectorBackendContext) {
    super(context);
    const mediapipeConfig = this.context.options.sounds.backendConfig.mediapipe;
    this.chunkSamples = mediapipeConfig.chunkSamples;

    this.tryInitializeAudioClassifier();
  }

  private async tryInitializeAudioClassifier(): Promise<void> {
    if (this.audioClassifier) return;

    await loadMediaPipeModule();

    const mediapipeConfig = this.context.options.sounds.backendConfig.mediapipe;
    const audioTasks = await FilesetResolver!.forAudioTasks(
      mediapipeConfig.wasmFilesUrl
    );
    this.audioClassifier = await AudioClassifier!.createFromOptions(
      audioTasks,
      {
        baseOptions: {modelAssetPath: mediapipeConfig.modelAssetPath},
      }
    );
  }

  /**
   * Normalizes audio data received as an ArrayBuffer (containing Int16 samples)
   * into a Float32Array with values in the range [-1.0, 1.0] that the MediaPipe
   * classifier can understand.
   * @param arrayBuffer - The raw audio data buffer.
   * @returns The normalized audio data.
   */
  override normalizeAudio(arrayBuffer: ArrayBuffer): NormalizedAudio {
    const int16Data = new Int16Array(arrayBuffer);
    const normalizedAudio = new Float32Array(int16Data.length);
    for (let i = 0; i < int16Data.length; i++) {
      normalizedAudio[i] = int16Data[i] / 32768.0;
    }
    return {data: normalizedAudio};
  }

  override classify(audio: NormalizedAudio): AudioClassifierResult | null {
    if (!this.audioClassifier) return null;

    const audioData = audio.data;
    for (let i = 0; i < audioData.length; i++) {
      this.accumulatedAudio.push(audioData[i]);
    }

    // chunkSamples is required because the MediaPipe AudioClassifier operates on
    // discrete chunks of audio data. We accumulate samples until we reach this
    // threshold before performing classification. If we do not accumulate enough samples,
    // the MediaPipe AudioClassifier returns a classification of "Silence" which is not
    // useful.
    if (this.accumulatedAudio.length >= this.chunkSamples) {
      const chunk = new Float32Array(
        this.accumulatedAudio.slice(0, this.chunkSamples)
      );
      this.accumulatedAudio = this.accumulatedAudio.slice(this.chunkSamples); // simple non-overlapping window

      const mediaPipeResult = this.audioClassifier.classify(
        chunk,
        this.context.sampleRate
      );

      const debugData = this.context.options.sounds.showDebugInfo
        ? this.populateDebugData({data: chunk})
        : undefined;

      return {
        items: mediaPipeResult,
        debug: debugData,
      };
    }
    return null;
  }

  override dispose() {
    this.audioClassifier?.close();
    this.audioClassifier = null;
    this.accumulatedAudio = [];
  }
}

import type * as MEDIAPIPE from '@mediapipe/tasks-vision';

import {SegmentationMask} from '../SegmentationMask';
import {
  BaseSegmenterBackend,
  SegmenterBackendContext,
} from '../SegmenterBackend';

let FilesetResolver: typeof MEDIAPIPE.FilesetResolver | undefined;
let ImageSegmenter: typeof MEDIAPIPE.ImageSegmenter | undefined;

// --- Attempt Dynamic Import ---
async function loadMediaPipeModule() {
  if (FilesetResolver && ImageSegmenter) {
    return;
  }
  try {
    const mediapipeModule = await import('@mediapipe/tasks-vision');
    FilesetResolver = mediapipeModule.FilesetResolver;
    ImageSegmenter = mediapipeModule.ImageSegmenter;
    console.log(
      "'@mediapipe/tasks-vision' MediaPipe Segmenter Module loaded successfully."
    );
  } catch (error) {
    console.error('Failed to load MediaPipe Tasks Vision module:', error);
    throw error;
  }
}

/**
 * The subset of the MediaPipe `MPMask` we read. Kept local so the mapping
 * helper can be unit-tested without the MediaPipe runtime.
 */
interface CategoryMask {
  getAsUint8Array(): Uint8Array;
  width: number;
  height: number;
  close(): void;
}

/**
 * Maps a MediaPipe category mask into a {@link SegmentationMask}. Copies the
 * buffer out before `close()` frees the underlying memory. Exported for tests.
 * @param mask - The MediaPipe category mask, or null/undefined if absent.
 * @returns The segmentation mask, or `null` when no mask was provided.
 */
export function categoryMaskToSegmentationMask(
  mask: CategoryMask | null | undefined
): SegmentationMask | null {
  if (!mask) {
    return null;
  }
  const result: SegmentationMask = {
    // Copy out before close() frees the underlying buffer.
    data: new Uint8Array(mask.getAsUint8Array()),
    width: mask.width,
    height: mask.height,
  };
  mask.close();
  return result;
}

/**
 * Segmentation backend backed by MediaPipe's `ImageSegmenter`. Runs locally on
 * the device using the configured selfie multiclass model.
 */
export class MediaPipeSegmenterBackend extends BaseSegmenterBackend {
  private imageSegmenter: MEDIAPIPE.ImageSegmenter | null = null;
  private initializationPromise: Promise<void>;

  constructor(context: SegmenterBackendContext) {
    super(context);
    this.initializationPromise = this.tryInitializeSegmenter();
  }

  private async tryInitializeSegmenter(): Promise<void> {
    await loadMediaPipeModule();
    const mediapipe = this.context.options.segmentation.backendConfig.mediapipe;
    const vision = await FilesetResolver!.forVisionTasks(
      mediapipe.wasmFilesUrl
    );
    this.imageSegmenter = await ImageSegmenter!.createFromOptions(vision, {
      baseOptions: {modelAssetPath: mediapipe.modelAssetPath, delegate: 'GPU'},
      runningMode: 'IMAGE',
      outputCategoryMask: mediapipe.outputCategoryMask,
      outputConfidenceMasks: false,
    });
  }

  protected override async isAvailable(): Promise<boolean> {
    try {
      await this.initializationPromise;
      return this.imageSegmenter !== null;
    } catch (e) {
      console.error('MediaPipe Image Segmenter is not available:', e);
      return false;
    }
  }

  protected override async getSnapshot(): Promise<{
    imageData: ImageData;
  } | null> {
    const imageData = await this.context.deviceCamera.getSnapshot({
      outputFormat: 'imageData',
    });
    if (!imageData) return null;
    return {imageData};
  }

  protected override async segment(snapshot: {
    imageData: ImageData;
  }): Promise<SegmentationMask | null> {
    await this.initializationPromise;
    if (!this.imageSegmenter) {
      return null;
    }
    // In IMAGE running mode segment() invokes the callback synchronously
    // before returning, so `out` is populated by the time we read it.
    let out: SegmentationMask | null = null;
    this.imageSegmenter.segment(snapshot.imageData, (result) => {
      out = categoryMaskToSegmentationMask(result.categoryMask);
    });
    return out;
  }

  override dispose() {
    this.imageSegmenter?.close();
    this.imageSegmenter = null;
  }
}

import type * as MEDIAPIPE from '@mediapipe/tasks-vision';
import {
  BaseDetectorBackend,
  DetectorBackendContext,
} from '../ObjectDetectorBackend';
import {CameraSnapshot, NormalizedDetectedObject} from '../ObjectDetector';

let FilesetResolver: typeof MEDIAPIPE.FilesetResolver | undefined;
let ObjectDetector: typeof MEDIAPIPE.ObjectDetector | undefined;

// --- Attempt Dynamic Import ---
async function loadMediaPipeModule() {
  if (FilesetResolver && ObjectDetector) {
    return;
  }
  try {
    const mediapipeModule = await import('@mediapipe/tasks-vision');
    FilesetResolver = mediapipeModule.FilesetResolver;
    ObjectDetector = mediapipeModule.ObjectDetector;
    console.log("'@mediapipe/tasks-vision' module loaded successfully.");
  } catch (error) {
    console.error('Failed to load MediaPipe module:', error);
    throw error;
  }
}

/**
 * Object detector backend implementation using MediaPipe's Object Detector.
 * Runs locally on the device.
 *
 * T - The type of additional data associated with the detected object (not used currently).
 */
export class MediaPipeDetectorBackend<T> extends BaseDetectorBackend<T> {
  private objectDetector: MEDIAPIPE.ObjectDetector | null = null;
  private initializationPromise: Promise<void>;

  constructor(context: DetectorBackendContext) {
    super(context);
    this.initializationPromise = this.tryInitializeObjectDetector();
  }

  protected async isAvailable(): Promise<boolean> {
    try {
      await this.initializationPromise;
      return true;
    } catch (e) {
      console.error('MediaPipe Object Detector is not available:', e);
      return false;
    }
  }

  protected async getSnapshot(): Promise<{imageData: ImageData} | null> {
    const imageData = await this.context.deviceCamera.getSnapshot({
      outputFormat: 'imageData',
    });
    if (!imageData) return null;
    return {imageData};
  }

  protected async detect(
    snapshot: CameraSnapshot
  ): Promise<NormalizedDetectedObject<T>[]> {
    await this.initializationPromise;

    if (!this.objectDetector) return [];

    const backendResponse = this.objectDetector.detect(snapshot.imageData!);
    if (!backendResponse) return [];

    const width = snapshot.imageData!.width;
    const height = snapshot.imageData!.height;

    return this.normalizeDetections(backendResponse, width, height);
  }

  private normalizeDetections(
    backendResponse: MEDIAPIPE.ObjectDetectorResult,
    width: number,
    height: number
  ): NormalizedDetectedObject<T>[] {
    // Map MediaPipe detections to NormalizedDetectedObject format.
    // We normalize the bounding box coordinates by the image dimensions.
    return backendResponse.detections.reduce<NormalizedDetectedObject<T>[]>(
      (acc: NormalizedDetectedObject<T>[], detection: MEDIAPIPE.Detection) => {
        const box = detection.boundingBox;
        if (box) {
          const category = detection.categories?.[0];
          const objectName =
            category?.categoryName || category?.displayName || 'unknown';
          acc.push({
            ymin: box.originY / height,
            xmin: box.originX / width,
            ymax: (box.originY + box.height) / height,
            xmax: (box.originX + box.width) / width,
            objectName: objectName,
          });
        }
        return acc;
      },
      []
    );
  }

  /**
   * Initializes the MediaPipe Object Detector if it has not already been initialized.
   * Loads the fileset resolver for vision tasks and creates the detector instance
   * with the configured model asset path and score threshold.
   */
  private async tryInitializeObjectDetector(): Promise<void> {
    if (this.objectDetector) return;

    await loadMediaPipeModule();

    const mediapipeOptions =
      this.context.options.objects.backendConfig.mediapipe;
    const vision = await FilesetResolver!.forVisionTasks(
      mediapipeOptions.wasmFilesUrl
    );
    this.objectDetector = await ObjectDetector!.createFromOptions(vision, {
      baseOptions: {
        modelAssetPath: mediapipeOptions.modelAssetPath,
      },
      scoreThreshold: mediapipeOptions.scoreThreshold,
    });
  }
}

